(648,1341,'Painful sexual intercourse.','en',2,'2026-06-24 20:26:42',NULL,NULL,'12958FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(649,1344,'Does the patient have shortness of breath while doing exercise or any physical activities?','en',2,'2026-06-24 20:26:42',NULL,NULL,'16185FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
