(1374,2882,'Abnormally infrequent menstruation.','en',2,'2026-06-24 20:27:15',NULL,NULL,'4172FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1375,2888,'Fractures of the femur.','en',2,'2026-06-24 20:27:15',NULL,NULL,'4165FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
