(8,'Admission Location','Patients may only be admitted to inpatient care in a location with this tag',2,'2026-06-24 20:24:50',0,NULL,NULL,NULL,'f5b9737b-14d5-402b-8475-dd558808e172',NULL,NULL),
(9,'Transfer Location','Patients may only be transfer to inpatient care in a location with this tag',2,'2026-06-24 20:24:50',0,NULL,NULL,NULL,'9783aba6-df7b-4969-be6e-1e03e7a08965',NULL,NULL),
(10,'Visit Location','A location where a patient may have a visit',2,'2026-06-24 20:24:50',0,NULL,NULL,NULL,'e2a1b3c4-d5e6-7890-1abc-def234567890',NULL,NULL);
